// Build the UTC search window for Calendly's availability endpoint.
// Accepts either a plain JSON body or Vapi's tool-call envelope ({ message: { toolCallList: [...] } }).
const raw = $json.body || {};
const msg = raw.message || {};
const call = (msg.toolCallList || msg.toolCalls || [])[0];
let args = call ? (call.arguments ?? call.parameters ?? call.function?.arguments ?? {}) : raw;
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
const toolCallId = call?.id || null;

const EVENT_TYPE_URI = 'https://api.calendly.com/event_types/REPLACE_WITH_EVENT_TYPE_ID'; // Synq Logic - AI Voice Booking (Internal)
const BUSINESS_TIMEZONE = 'America/New_York';
const DAY = 24 * 60 * 60 * 1000;

// An unknown timezone name from the caller would crash the formatter later, so fall back to the business default.
let callerTz = args.caller_timezone || BUSINESS_TIMEZONE;
try { new Intl.DateTimeFormat('en-US', { timeZone: callerTz }); } catch (e) { callerTz = BUSINESS_TIMEZONE; }

const now = new Date(Date.now() + 60 * 60 * 1000); // start 1 hour out so we never offer a slot that's already passed
let start = now;

// Optional: the caller asks for a specific day (YYYY-MM-DD). Search from that day instead of from today.
let preferred = null;
const pd = String(args.preferred_date || '').trim();
if (/^\d{4}-\d{2}-\d{2}$/.test(pd)) {
  const d = new Date(pd + 'T00:00:00Z');
  if (!isNaN(d.getTime())) {
    const s = new Date(d.getTime() - 14 * 3600 * 1000); // widen by 14h so any timezone's start of day is covered
    if (s.getTime() > now.getTime()) start = s;
    preferred = pd;
  }
}
const end = new Date(start.getTime() + 20 * DAY); // 20-day window, under Calendly's 31-day cap

return [{
  json: {
    event_type: EVENT_TYPE_URI,
    start_time: start.toISOString(),
    end_time: end.toISOString(),
    business_timezone: BUSINESS_TIMEZONE,
    caller_timezone: callerTz,
    preferred_date: preferred,
    toolCallId,
  },
}];

// Turn Calendly's raw slot list into a few speakable options SPREAD ACROSS DIFFERENT DAYS,
// so the agent can offer real variety instead of three back-to-back slots on one day.
const ctx = $('Build search window').first().json;
const tz = ctx.caller_timezone;
const collection = $input.first().json.collection || [];
const available = collection.filter((s) => s.status === 'available');

const dayKey = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' });
const spokenFmt = new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit' });
const dayFmt = new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'long', month: 'long', day: 'numeric' });

// Group open slots by the caller's local calendar day.
const byDay = new Map();
for (const s of available) {
  const key = dayKey.format(new Date(s.start_time));
  if (ctx.preferred_date && key < ctx.preferred_date) continue; // only days on/after the requested date
  if (!byDay.has(key)) byDay.set(key, []);
  byDay.get(key).push(s);
}
const days = [...byDay.keys()].sort();

// Up to 3 different days; on each day offer the first slot plus a later one (at least 3 hours apart) for variety.
const picked = [];
for (const key of days.slice(0, 3)) {
  const list = byDay.get(key);
  const first = list[0];
  const later = list.find((s) => new Date(s.start_time) - new Date(first.start_time) >= 3 * 3600 * 1000) || list[1];
  picked.push(first);
  if (later && later !== first) picked.push(later);
}

const slots = picked.map((s) => ({
  start_time: s.start_time, // UTC ISO string - pass this back verbatim when booking
  spoken: spokenFmt.format(new Date(s.start_time)),
  date: dayKey.format(new Date(s.start_time)),
}));

const searchedThrough = dayFmt.format(new Date(ctx.end_time));
const moreDays = days.length > 3;

return [{
  json: {
    ok: slots.length > 0,
    message: slots.length
      ? `Found openings on ${Math.min(days.length, 3)} different day${Math.min(days.length, 3) > 1 ? 's' : ''}${moreDays ? ', and there are more open days after these' : ''}. Searched through ${searchedThrough}. If none suit the caller, ask which day they prefer and call this again with preferred_date (YYYY-MM-DD).`
      : `No open times found through ${searchedThrough}. Offer to check a later date with preferred_date, or take a callback request instead.`,
    searched_through: searchedThrough,
    more_days_available: moreDays,
    slots,
  },
}];
